import{_ as e,o as n,c as a,a0 as r}from"./chunks/framework.Nb-0NFIl.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core/ecs/entityhandle.md","filePath":"core/ecs/entityhandle.md"}'),o={name:"core/ecs/entityhandle.md"};function s(i,t,l,d,h,c){return n(),a("div",null,[...t[0]||(t[0]=[r('<h6 id="version-0-7-1" tabindex="-1">version: 0.7.1 <a class="header-anchor" href="#version-0-7-1" aria-label="Permalink to &quot;version: 0.7.1&quot;">​</a></h6><hr><h2 id="entityhandle" tabindex="-1">EntityHandle <a class="header-anchor" href="#entityhandle" aria-label="Permalink to &quot;EntityHandle&quot;">​</a></h2><h2 id="entityhandle-1" tabindex="-1">EntityHandle <a class="header-anchor" href="#entityhandle-1" aria-label="Permalink to &quot;EntityHandle&quot;">​</a></h2><p>The base class for all high-level Doriax objects that wrap an ECS entity. <code>EntityHandle</code> stores a reference to its owning <code>Scene</code> and its <code>Entity</code> identifier, giving C++ code a convenient handle to a scene entity without having to interact with the raw ECS API.</p><p>Most classes in the Doriax API — <code>Object</code>, <code>Action</code>, <code>Sound</code>, <code>Skybox</code>, etc. — inherit from <code>EntityHandle</code>.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Property</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://en.cppreference.com/w/cpp/string/basic_string" target="_blank" rel="noreferrer"><strong>std::string</strong></a></td><td style="text-align:left;"><a href="./entityhandle-name.html"><strong>name</strong></a></td><td style="text-align:left;">Human-readable tag for this entity, used by the editor hierarchy and for debugging or lookup.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./entityhandle-entity-owned.html"><strong>entityOwned</strong></a></td><td style="text-align:left;">Whether this handle owns its entity and destroys it when the handle is destroyed.</td></tr></tbody></table><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Arguments</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./../scene/scene.html"><strong>Scene*</strong></a> scene</td><td style="text-align:left;">Creates a new entity in the scene. The handle owns the entity.</td></tr><tr><td style="text-align:left;"><a href="./../scene/scene.html"><strong>Scene*</strong></a> scene, <a href="./entity.html"><strong>Entity</strong></a> entity</td><td style="text-align:left;">Wraps an existing entity. The handle does not own the entity.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/const" target="_blank" rel="noreferrer"><strong>const</strong></a> <a href="./entityhandle.html"><strong>EntityHandle&amp;</strong></a> rhs</td><td style="text-align:left;">Copy constructor. Copies are non-owning observers; the source keeps sole ownership.</td></tr><tr><td style="text-align:left;"><a href="./entityhandle.html"><strong>EntityHandle&amp;&amp;</strong></a> rhs</td><td style="text-align:left;">Move constructor. Transfers ownership to the new handle and leaves the source non-owning.</td></tr></tbody></table><p><code>EntityHandle</code> follows single-owner semantics so an entity is never destroyed twice. Copying produces a non-owning observer that references the same entity without owning it, while moving transfers ownership to the destination and leaves the source as a non-owning observer. Wrapping an existing entity with <code>EntityHandle(scene, entity)</code> never takes ownership, so wrapped handles are safe to copy and discard.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Result</th><th style="text-align:left;">Method</th><th style="text-align:left;">Arguments</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./../scene/scene.html"><strong>Scene*</strong></a></td><td style="text-align:left;"><a href="./entityhandle-get-scene.html"><strong>getScene</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Returns a pointer to the owning scene.</td></tr><tr><td style="text-align:left;"><a href="./entity.html"><strong>Entity</strong></a></td><td style="text-align:left;"><a href="./entityhandle-get-entity.html"><strong>getEntity</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Returns the raw ECS entity identifier.</td></tr></tbody></table><hr><p>Found an issue? <a href="https://github.com/JordanGrant3D/doriax-jord-docs/issues" target="_blank" rel="noreferrer">Report it here</a>.</p>',15)])])}const f=e(o,[["render",s]]);export{g as __pageData,f as default};
